 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    # The full line of 2s marks the side toward which the objects slide.
    direction = None
    for r in range(h):
        if all(v == 2 for v in grid[r]):
            direction = (1, 0) if r == 0 else (-1, 0)
            break
    if direction is None:
        for c in range(w):
            if all(grid[r][c] == 2 for r in range(h)):
                direction = (0, 1) if c == 0 else (0, -1)
                break
    if direction is None:
        return [row[:] for row in grid]
    dr, dc = direction

    seen = set()
    pieces = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 0 or grid[r][c] == 2 or (r, c) in seen:
                continue
            color = grid[r][c]
            stack = [(r, c)]
            seen.add((r, c))
            piece = []
            while stack:
                rr, cc = stack.pop()
                piece.append((rr, cc, color))
                for nr, nc in ((rr-1,cc),(rr+1,cc),(rr,cc-1),(rr,cc+1)):
                    if (0 <= nr < h and 0 <= nc < w and (nr,nc) not in seen
                            and grid[nr][nc] == color):
                        seen.add((nr,nc))
                        stack.append((nr,nc))
            pieces.append(piece)

    # Place pieces nearest the marked edge first so later pieces stack on them.
    if dr == 1:
        pieces.sort(key=lambda p: -max(r for r,c,_ in p))
    elif dr == -1:
        pieces.sort(key=lambda p: min(r for r,c,_ in p))
    elif dc == 1:
        pieces.sort(key=lambda p: -max(c for r,c,_ in p))
    else:
        pieces.sort(key=lambda p: min(c for r,c,_ in p))

    out = [[2 if grid[r][c] == 2 else 0 for c in range(w)] for r in range(h)]
    for piece in pieces:
        shift = 0
        while True:
            nrshift = shift + 1
            clear = True
            for r, c, color in piece:
                nr, nc = r + dr*nrshift, c + dc*nrshift
                if not (0 <= nr < h and 0 <= nc < w) or out[nr][nc] != 0:
                    clear = False
                    break
            if not clear:
                break
            shift = nrshift
        for r, c, color in piece:
            out[r + dr*shift][c + dc*shift] = color
    return out
